/**
 * assets/js/vendor/idb-keyval.min.js
 * Lightweight IndexedDB Key-Value Store (jakearchibald/idb-keyval pattern, Apache-2.0)
 * Exposes window.idbKeyval: { get, set, del, clear, keys, createStore }
 */
(function (global) {
  'use strict';

  function promisifyRequest(request) {
    return new Promise((resolve, reject) => {
      request.oncomplete = request.onsuccess = () => resolve(request.result);
      request.onabort = request.onerror = () => reject(request.error);
    });
  }

  function createStore(dbName, storeName) {
    let dbp = null;
    const getDB = () => {
      if (dbp) return dbp;
      if (typeof indexedDB === 'undefined') {
        return Promise.reject(new Error('IndexedDB not supported'));
      }
      const req = indexedDB.open(dbName, 1);
      req.onupgradeneeded = () => {
        if (!req.result.objectStoreNames.contains(storeName)) {
          req.result.createObjectStore(storeName);
        }
      };
      dbp = promisifyRequest(req);
      return dbp;
    };
    return (txMode, callback) =>
      getDB().then((db) =>
        callback(db.transaction(storeName, txMode).objectStore(storeName))
      );
  }

  let defaultGetStoreFunc;
  function defaultGetStore() {
    if (!defaultGetStoreFunc) {
      defaultGetStoreFunc = createStore('sheetapp2-idb', 'keyval');
    }
    return defaultGetStoreFunc;
  }

  function get(key, customStore = defaultGetStore()) {
    return customStore('readonly', (store) => promisifyRequest(store.get(key)));
  }

  function set(key, value, customStore = defaultGetStore()) {
    return customStore('readwrite', (store) => {
      store.put(value, key);
      return promisifyRequest(store.transaction);
    });
  }

  function del(key, customStore = defaultGetStore()) {
    return customStore('readwrite', (store) => {
      store.delete(key);
      return promisifyRequest(store.transaction);
    });
  }

  function clear(customStore = defaultGetStore()) {
    return customStore('readwrite', (store) => {
      store.clear();
      return promisifyRequest(store.transaction);
    });
  }

  function keys(customStore = defaultGetStore()) {
    return customStore('readonly', (store) => {
      if (store.getAllKeys) {
        return promisifyRequest(store.getAllKeys());
      }
      const items = [];
      return new Promise((resolve, reject) => {
        const req = store.openCursor();
        req.onerror = () => reject(req.error);
        req.onsuccess = () => {
          const cursor = req.result;
          if (!cursor) { resolve(items); return; }
          items.push(cursor.key);
          cursor.continue();
        };
      });
    });
  }

  const idbKeyval = { get, set, del, clear, keys, createStore };
  global.idbKeyval = idbKeyval;
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = idbKeyval;
  }
})(typeof window !== 'undefined' ? window : globalThis);
